<?php $pageTitle='Room '.$room['code'].' layout';$byRow=[];foreach($seats as $seat)$byRow[$seat['row_no']][]=$seat; ?>
<section class="page-heading"><div><p class="eyebrow"><?= e($room['building']) ?></p><h1><?= e($room['code']) ?> seat map</h1><p><?= (int)$room['usable_capacity'] ?> usable seats from <?= (int)$room['physical_capacity'] ?> physical positions.</p></div><a class="secondary-button" href="<?= e(url('rooms/'.$room['id'].'/edit')) ?>">Edit geometry</a></section><section class="panel seat-map"><div class="whiteboard">WHITE BOARD</div><?php foreach($byRow as $row=>$rowSeats):?><div class="seat-row" style="--columns:<?= (int)$room['columns_count'] ?>"><?php foreach($rowSeats as $seat):?><div class="seat <?= $seat['is_blocked']?'blocked':'' ?>"><strong><?= e($seat['seat_label']) ?></strong><span><?= e($seat['desk_group']) ?></span></div><?php endforeach;?></div><?php endforeach;?></section>

